<?php require_once "../config/auth.php";require_login();$u=user();$err="";$ok="";$services=db()->query("SELECT * FROM services WHERE status='active' ORDER BY category,name")->fetchAll();if($_SERVER["REQUEST_METHOD"]==="POST"){check_csrf();$sid=(int)$_POST["service_id"];$link=trim($_POST["link"]);$qty=(int)$_POST["quantity"];$q=db()->prepare("SELECT * FROM services WHERE id=? AND status='active'");$q->execute([$sid]);$s=$q->fetch();if(!$s||!filter_var($link,FILTER_VALIDATE_URL)||$qty<$s["min_qty"]||$qty>$s["max_qty"])$err="Invalid service, URL or quantity.";else{$charge=round($qty*$s["rate_per_1000"]/1000,2);$pdo=db();$pdo->beginTransaction();try{$q=$pdo->prepare("SELECT balance FROM users WHERE id=? FOR UPDATE");$q->execute([$u["id"]]);if((float)$q->fetchColumn()<$charge)throw new Exception("Insufficient balance.");$pdo->prepare("UPDATE users SET balance=balance-? WHERE id=?")->execute([$charge,$u["id"]]);$pdo->prepare("INSERT INTO orders(user_id,service_id,link,quantity,charge) VALUES(?,?,?,?,?)")->execute([$u["id"],$sid,$link,$qty,$charge]);$pdo->prepare("INSERT INTO transactions(user_id,type,amount,description) VALUES(?,'order',?,'Order charge')")->execute([$u["id"],-$charge]);$pdo->commit();$ok="Order created successfully.";}catch(Exception $x){$pdo->rollBack();$err=$x->getMessage();}}}?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="style.css"></head><body><main><form class="box wide" method="post"><h1>New Order</h1><?php if($err):?><div class="error"><?=e($err)?></div><?php endif;?><?php if($ok):?><div class="success"><?=$ok?></div><?php endif;?><input type="hidden" name="csrf" value="<?=e(csrf())?>"><select name="service_id" required><option value="">Select service</option><?php foreach($services as $s):?><option value="<?=$s["id"]?>"><?=e($s["category"]." — ".$s["name"]." | ৳".$s["rate_per_1000"]."/1K")?></option><?php endforeach;?></select><input name="link" placeholder="https://..." required><input name="quantity" type="number" placeholder="Quantity" required><button>🚀 Place Order</button></form></main></body></html>